use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTP: one fetch. A transport failure is a value, so a feed that is
        // down still yields a report (with zero characters fetched). A URL
        // outside the allowlist traps at the boundary, by design.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let n = body.chars().count();
                u32::try_from(n).unwrap_or(u32::MAX)
            }
            Err(_) => 0,
        };

        // Notifier: report the heartbeat to the digest channel.
        let message = format!(
            "heartbeat at {} seconds: fetched {} characters from {}",
            seconds, fetched, feed_url
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // The contract requires `notified == true` on every output. If the
        // channel never accepts the notification, do not fabricate success:
        // fail the run instead of producing an output that breaks the contract.
        if !notified {
            panic!("notification was not accepted by the digest channel");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
